extern "C" unsigned int strlen(const char *);

struct string_buf {
  void *data;
  int ref_count;
  int char_length;
  int block_length;
  int max_blocks;
};

class stringx {
  char *chars;
  string_buf *my_buf;
public:
  stringx();
  stringx(const stringx&);
  ~stringx();
  void make_room(int);
  void append(const stringx&);
  void append(const char *, int);
  friend stringx operator+(const stringx&, const stringx&);
  friend stringx operator+(const stringx&, const char *);
};

inline stringx operator+(const stringx& lhs, const stringx& rhs)
{
  stringx foo;
  foo.make_room(lhs.my_buf->char_length + rhs.my_buf->char_length);
  foo.append(lhs);
  foo.append(rhs);
  return foo;
}

inline stringx operator+(const stringx& lhs, const char *rhs)
{
  stringx foo;
  int len = strlen(rhs);
  foo.make_room(len + lhs.my_buf->char_length);
  foo.append(lhs);
  foo.append(rhs, len);
  return foo;
}

class script_instance {
  void *owner;
  stringx name;
public:
  const stringx& get_name() const { return name; }
};

class vm_executable {
  void *owner;
  stringx name;
  stringx fullname;
public:
  const stringx& get_fullname() const { return fullname; }
};

class vm_thread {
  script_instance *inst;
  const vm_executable *ex;
public:
  script_instance *get_instance() const { return inst; }
  const vm_executable *get_executable() const { return ex; }
};

class vm_stack {
public:
  int salloc;
  char *buffer;
  char *SP;
private:
  vm_thread *my_thread;
public:
  char *get_SP() const { return SP; }
  vm_thread *get_thread() const { return my_thread; }
  void pop(int n) { SP += -n; }
  bool push(const char *, int);
};

void error(const stringx&);

class script_library_class {
public:
  class function {
  public:
    enum entry_t { FIRST_ENTRY, RECALL_ENTRY };
    virtual bool operator()(vm_stack&, entry_t) { return true; }
  };
};

struct vector3d { float x, y, z; };
class vector3d_list {
public:
  typedef vector3d *iterator;
private:
  vector3d *start;
  vector3d *finish;
  vector3d *end_of_storage;
public:
  iterator end() { return finish; }
};
typedef vector3d_list *vm_vector3d_list_t;
typedef vector3d_list::iterator vm_vector3d_list_iterator_t;

class slf_vector3d_list_rbegin_t : public script_library_class::function {
public:
  struct parms_t { vm_vector3d_list_t me; };
  virtual bool operator()(vm_stack& stack, entry_t entry)
  {
    stack.pop(sizeof(parms_t));
    parms_t* parms = (parms_t*)stack.get_SP();
    vm_vector3d_list_iterator_t result = parms->me->end();
    --result;
    if (!stack.push((char*)&result,sizeof(result)) )
      error( stack.get_thread()->get_instance()->get_name() + ": stack overflow in " + stack.get_thread()->get_executable()->get_fullname() );
    return true;
  }
};
